text:
{
  "pass": false,
  "problems": [
    {
      "type": "ふりがなの読み",
      "where": "summary の es",
      "detail": "「オーバーナイト物」の「物」に「ぶつ」とふりがながついていますが、金融用語では「もの（オーバーナイトもの）」と読みます。",
      "fix": "オーバーナイト物《もの》に直します。"
    },
    {
      "type": "中身のずれ",
      "where": "summary の hs",
      "detail": "stdにある「9月18日決定、9月24日から適用」や「賛成8・反対1」の情報が抜けており、stdにない物価安定の目的についての説明が足されています。",
      "fix": "stdに合わせて、9月の決定・適用の時期や、10月会合の採決結果（賛成8・反対1）を含めるように書き直します。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "stdは「政策金利の変更が住宅ローンなどの借入れ金利にどうつながるか」を問う文ですが、hsは預金利息についての導入になっており、政策金利や借入れ金利とのつながりという話の主旨からずれています。",
      "fix": "「国の政策金利が変わると、住宅ローンなどのお金を借りるときの金利にどう影響するのでしょう？」のように、stdの内容に沿った文に直します。"
    },
    {
      "type": "名前と数字",
      "where": "blocks/4/text の hs",
      "detail": "stdにある年号（2026年）や提案者の名前（高田委員）が抜け、結果が据え置きになったことも明確に書かれていません。",
      "fix": "「2026年10月30日の会合では金利をそのままにすることを決めました（賛成8、反対1）。高田委員が出した1.5％程度への引き上げ案は、反対が多くて否決されました。」のように直します。"
    }
  ]
}
